'use strict';

(function(){
  addRepairKB({id:'sato-cl4nx-printhead-replace-exact',brand:'SATO',models:['CL4NX Plus'],title:'CL4NX Plus｜原廠 Printhead 更換程序與 Head Error 1012 判斷',category:'原廠維護／Printhead',severity:'A｜原廠',summary:'SATO 官方允許 CL4NX Plus 直接更換損壞或磨耗的 Printhead；但 1012 Head Error 先確認 print elements 磨耗/損傷，再決定更換。',keyFacts:['更換前必須關機並拔除 AC 電源；列印後 Printhead 周邊高溫，要等冷卻。','官方建議戴手套，避免傷害/污染 Printhead。','CL4NX Plus Printhead 有 2 個 connectors；CL6NX Plus 為 3 個，不可把兩機程序混用。','UHF RFID 機型天線裝在 Printhead，拆頭時不可過度拉扯天線線材。','Error 1012 的官方原因包括 print elements 磨耗，或 Printhead 已磨耗/損傷；後者可更換 Printhead。'],engineering:['拆前記錄 DPI/設定與原頭狀態。','Push head lock lever 向後解鎖，移除 media/ribbon，再按 release lever 取下 Printhead。','新 Head connectors 全部接回並確認卡入 click，不碰敏感列印面。'],verify:['開機無 1012','Head Check 正常','測試圖無固定壞點','實際條碼掃描通過'],flow:[['確認故障證據','1012、固定壞點、磨耗或損傷。',['支持 Head','證據不足'],'證據不足先清潔/測試。'],['安全斷電冷卻','拔 AC、等 Head 冷卻、戴手套。',['完成','未完成'],'未完成不拆。'],['拆換 Printhead','Head lock→移除耗材→release→拔 2 connectors→換新。',['完成','遇到 RFID/異常'],'RFID 注意 antenna cable。'],['重新裝耗材','Ribbon/Media 正確裝回並 lock Head。',['完成','異常'],'先修裝配。'],['品質/Head Check 驗證','Self/Test、Barcode scan、連印。',['通過','失敗'],'失敗回 Cable/Drive/Head 檢查。']],sources:['sato_clnx_replace_head','sato_clnx_head_error','sato_clnx_errors'],evidence:'source-backed'});

  addRepairKB({id:'sato-cl4nx-platen-replace-exact',brand:'SATO',models:['CL4NX Plus'],title:'CL4NX Plus｜原廠 Platen Roller 更換判斷與安裝方向',category:'原廠維護／Platen',severity:'A｜原廠',summary:'SATO 官方提供 CL4NX Plus Platen Roller 更換程序，並以左側 striped marking 開始淡化作為一般更換參考；真正是否更換仍以磨耗是否影響列印品質為準。',keyFacts:['Platen 左側有 striped marking；標記開始淡化可視為一般更換指標。','官方明確說這只是 general guideline，實際磨耗依使用 media 而異；只要已影響列印品質就應更換。','更換前關機、拔 AC，解鎖 Printhead。','裝新 Platen 時，左右端 tab 都需朝上並確實卡入對應 groove。'],engineering:['先清潔排除殘膠/污染，不把髒污誤判磨耗。','拆時抬起 platen lever 解鎖後拉出；裝回確認 drive end 與 driven end 都到位。','更換後轉動確認無偏心，再做定位/品質長測。'],verify:['手轉順暢','FEED不打滑','定位無累積漂移','左右品質一致'],flow:[['檢查 striped marking/表面','看標記、磨耗、凹痕與品質影響。',['需換','可繼續使用'],'可用就不預防性亂換。'],['安全斷電','拔 AC、開蓋、解 Head lock。',['完成','未完成'],'先安全。'],['拆舊 Platen','抬 lever 解鎖後抽出。',['完成','卡滯'],'卡滯不要硬撬。'],['依方向裝新件','左右 tab 朝上且進 groove，再鎖 lever。',['完成','未到位'],'未到位重裝。'],['Calibration/長測','FEED＋品質＋定位。',['通過','失敗'],'失敗查壓力/Sensor/安裝。']],sources:['sato_clnx_replace_platen','sato_clnx_maintenance'],evidence:'source-backed'});

  addRepairKB({id:'sato-cl4nx-maintenance-defaults',brand:'SATO',models:['CL4NX Plus'],title:'CL4NX Plus｜原廠 Maintenance Notifications 初始值：Cleaning / Head / Cutter / Platen',category:'原廠維護／保養週期',severity:'A｜原廠',summary:'CL4NX Plus System 初始值提供 Cleaning、Printhead、Cutter、Platen notification interval，可作為機器通知設定的基準，但不是「到了數字就一定壞」的強制壽命。',keyFacts:['Factory initial：Cleaning Interval 400 m。','Factory initial：Printhead Interval 100 km。','Factory initial：Cutter Life 1000 K cuts。','Factory initial：Platen Interval 100 km。','Clean/Change notifications 初始均為 Disabled；User/Factory reset 會影響這些設定。','這些是通知初始值，不等同所有環境的實際零件壽命。'],engineering:['重粉塵、黏膠、特殊耗材應依實際污染/磨耗提早清潔。','不要因 Counter 到值就不檢查直接換昂貴零件。','若客戶啟用通知，維修時記錄 counter 與實際磨耗，逐步建立自己的 PM 基準。'],verify:['Notification 設定符合客戶需求','清潔後品質正常','Counter/維修記錄留存','未將初始值誤當保固壽命'],flow:[['讀目前通知設定','Clean/Head/Cutter/Platen。',['已讀','無法讀'],'保存現況。'],['比對原廠 initial values','400m / 100km / 1000K cuts / 100km。',['完成','設定不同'],'不同不一定錯。'],['檢查實際磨耗','依污染、品質與機構狀態。',['需要保養/換件','狀態正常'],'以實機優先。'],['設定通知策略','依客戶使用量與環境決定是否 Enable/調整。',['完成','維持原設定'],'避免擅改。'],['建立 PM 紀錄','記 counter、日期、耗材、處置。',['完成','待補'],'讓後續週期有依據。']],sources:['sato_clnx_system_defaults','sato_clnx_maintenance'],evidence:'source-backed'});
})();
